import{_ as p,c as e,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"26、【大畜】 乾下艮上","description":"周易闡真 - 26、【大畜】 乾下艮上","frontmatter":{"title":"26、【大畜】 乾下艮上","description":"周易闡真 - 26、【大畜】 乾下艮上"},"headers":[],"relativePath":"classics/chanzhen/027.md","filePath":"classics/chanzhen/027.md"}'),s={name:"classics/chanzhen/027.md"};function n(c,a,i,o,l,h){return t(),e("div",null,[...a[0]||(a[0]=[r('<blockquote><p>彖曰：大畜，剛健篤實，輝光日新。其德剛上而尚賢，能止健，大正也。不家食吉，養賢也。利涉大川，應乎天也。</p></blockquote><h1 id="_26、【大畜】-乾下艮上" tabindex="-1">26、【大畜】 乾下艮上 <a class="header-anchor" href="#_26、【大畜】-乾下艮上" aria-label="Permalink to “26、【大畜】 乾下艮上”">​</a></h1><p>初九：有厲，利已。</p><p>九二：輿說復副本。</p><p>九三：良馬逐，利艱貞。日閒輿衛，利有攸往。</p><p>六四：童牛之牿，元吉。</p><p>六五：豶豕之牙，吉。</p><p>上九：何天之衢，亨。</p><h2 id="孔易闡真-​" tabindex="-1">孔易闡真 ​ <a class="header-anchor" href="#孔易闡真-​" aria-label="Permalink to “孔易闡真 ​”">​</a></h2><p>大象：天在山中，大畜。君子以多識前言往行，以畜其德。</p><p>大畜者，積聚大也。上艮山，下乾天，是天在山中也。天大山小，外小而內大，此大畜之象也。</p><p>君子有見於此，知人之不能增益其德者，皆由自恃才智，自高自大，不知法古聖先賢之故。以是多識前人之言、往古之行，擴充識見，以畜其德焉。聖賢心法命脈，皆藏於經書之中。前人之言，言其德也；往古之行，行其德也。若能博學而篤志，切問而近思，則晤對聖賢，所言者皆前人之言，所行者皆往古之行。言行無虧，其德日畜日大，方且儘性至命，性命俱了，與天同長久，與山同堅固，其畜之大何如乎!</p><h2 id="悟元子註解-​" tabindex="-1">悟元子註解 ​ <a class="header-anchor" href="#悟元子註解-​" aria-label="Permalink to “悟元子註解 ​”">​</a></h2><p>畜，敕六反。說，音脫。復副本，音福。豶，音焚。衢，音渠。</p><p>大畜者，大養之義。卦德上艮止，下乾健，有健而能止，故謂大畜。此溫養聖胎之卦，承上覆卦而來。復者，復其先天之氣也。當先天之氣來複，於內自微而著，還其乾元面目，命基已固，聖胎已結，自有為而入無為，可以謹封牢藏，防危慮險，溫養沐浴，期於大化神妙不測之地，為金剛不壞之物。</p><p>是道也，利於止健，不利於用健，故曰利貞。貞者，靜也。止健者，養健也。養健之功，即守中抱一之功。守中抱一，宜靜而不宜動，靜則保健，動則傷健。止非絕世離塵，靜非空寂無為，其中有抽添加減，內外兼修之道，故必不家食，方能大畜而致吉。不家食者，是外爐加減，內運真火，止於內而又止於外，綿綿若存，勿忘勿助，即遇大險大難之境，不動不搖，方是真畜，方是畜之大，是以又利於涉大川也。大川之涉，所以養於內而驗於外，即九年面壁之功。面壁者，如壁列萬仞，離種種邊，止於不識不知，打破虛空地位也。打破虛空，聖胎脫化，形神俱妙，與道合真，畜之大而成之大，與天為徒矣。</p><p>初九，在大畜之始，進健則兇，止健則吉，有厲利己，正當棄有為而入無為之時。此養健於初也。</p><p>九二，剛以柔用，保惜聖胎，待時脫化，如輿說復副本，則車不行矣。修道者，剛健歸中，聖胎已結，急須住火停輪，不可更進其健，有傷元氣者。此養健得中也。</p><p>九三，養健已到，氣足神全，誠於中而將達於外，如良馬逐而欲行矣。雖然聖胎完成，猶有一身陰氣未嘗化盡，全在艱辛守貞，一意不散，如日閒輿衛，時時防跌，十月功完，自然脫化，則利有攸往矣。此養健防危也。</p><p>六四，應於初陽，健德方生，而即養之，如童牛之牿也。牛性馴順，其健在角，牛在於童，其角方生，方生能養，元氣不散，漸長漸養，終必養至於純全之處，其吉已在於方健之養。此養健而堅固元氣也。</p><p>六五，正當大畜之時，以陰養陽，如豶賁豕也。豕之去勢曰豶。豕去其勢，則氣質俱化，虛心而全實腹，如豶豕之牙也。豕柔牙剛，以柔養剛，剛得柔養而無傷。此養健而混合陰陽也。</p><p>上九，在大畜之終，功完行滿，霹靂一聲，真人出現，驚愚駭俗，始於有作無人見，及至無為眾始知，何天之衢，誰不稱哉！</p><p>修道者，而至於脫胎成真，身外有身，超出乎天地之外，不但成己，而且成物，畜之大而顯之大，其亨為何如乎！此養健而歸於神化也。</p><p>然則溫養聖胎之道，總要知的大畜健而止。既健又止，始則有為，終則無為，健而止於至善無惡，渾然太極，一氣流行，有無俱不立，物我悉歸空，性命雙修之道盡矣。</p>',24)])])}const m=p(s,[["render",n]]);export{d as __pageData,m as default};
